impl Document {
    pub(crate) fn compare_abstract_implementation_data_type(
        &self,
        other: &Document,
        a: &AbstractImplementationDataType,
        b: &AbstractImplementationDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_autosar_data_type(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_abstract_implementation_data_type_element(
        &self,
        other: &Document,
        a: &AbstractImplementationDataTypeElement,
        b: &AbstractImplementationDataTypeElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_implementation_data_type(
        &self,
        other: &Document,
        a: &ImplementationDataType,
        b: &ImplementationDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_implementation_data_type(other, a.base(), b.base(), path)?;
        if a.get_dynamic_array_size_profile() != b.get_dynamic_array_size_profile() {
            return Err(format!("{path}: DYNAMIC_ARRAY_SIZE_PROFILE mismatch"));
        }
        if a.get_is_struct_with_optional_element() != b.get_is_struct_with_optional_element() {
            return Err(format!("{path}: IS_STRUCT_WITH_OPTIONAL_ELEMENT mismatch"));
        }
        let list_a = a.get_sub_elements();
        let list_b = b.get_sub_elements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SUB_ELEMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .implementation_data_type_elements
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.SUB_ELEMENTS[{index}]: id not found in own arena")
                })?;
            let y = other
                .implementation_data_type_elements
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.SUB_ELEMENTS[{index}]: id not found in other arena")
                })?;
            self.compare_implementation_data_type_element(
                other,
                x,
                y,
                &format!("{path}.SUB_ELEMENTS[{index}]"),
            )?;
        }
        if a.get_symbol_props() != b.get_symbol_props() {
            return Err(format!("{path}: SYMBOL_PROPS mismatch"));
        }
        if a.get_type_emitter() != b.get_type_emitter() {
            return Err(format!("{path}: TYPE_EMITTER mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_implementation_data_type_element(
        &self,
        other: &Document,
        a: &ImplementationDataTypeElement,
        b: &ImplementationDataTypeElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_implementation_data_type_element(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_array_impl_policy() != b.get_array_impl_policy() {
            return Err(format!("{path}: ARRAY_IMPL_POLICY mismatch"));
        }
        if a.get_array_size() != b.get_array_size() {
            return Err(format!("{path}: ARRAY_SIZE mismatch"));
        }
        if a.get_array_size_handling() != b.get_array_size_handling() {
            return Err(format!("{path}: ARRAY_SIZE_HANDLING mismatch"));
        }
        if a.get_array_size_semantics() != b.get_array_size_semantics() {
            return Err(format!("{path}: ARRAY_SIZE_SEMANTICS mismatch"));
        }
        if a.get_is_optional() != b.get_is_optional() {
            return Err(format!("{path}: IS_OPTIONAL mismatch"));
        }
        let list_a = a.get_sub_elements();
        let list_b = b.get_sub_elements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SUB_ELEMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .implementation_data_type_elements
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.SUB_ELEMENTS[{index}]: id not found in own arena")
                })?;
            let y = other
                .implementation_data_type_elements
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.SUB_ELEMENTS[{index}]: id not found in other arena")
                })?;
            self.compare_implementation_data_type_element(
                other,
                x,
                y,
                &format!("{path}.SUB_ELEMENTS[{index}]"),
            )?;
        }
        if a.get_sw_data_def_props() != b.get_sw_data_def_props() {
            return Err(format!("{path}: SW_DATA_DEF_PROPS mismatch"));
        }
        Ok(())
    }
}
